#[test]
fn resultado_memoizado_nao_recarrega_fonte_para_emitir_carrier() {
    struct CountWorld<'a> { base: &'a FontWorld, regular_loads: std::sync::atomic::AtomicUsize }
    impl World for CountWorld<'_> {
        fn library(&self) -> &Library { self.base.library() }
        fn book(&self) -> &FontBook { self.base.book() }
        fn main(&self) -> FileId { self.base.main() }
        fn source(&self, id: FileId) -> FileResult<Source> { self.base.source(id) }
        fn file(&self, id: FileId) -> FileResult<Bytes> { self.base.file(id) }
        fn today(&self, offset: Option<typst_core::entities::duration::Duration>) -> Option<Datetime> { self.base.today(offset) }
        fn font(&self, index: usize) -> Option<Font> {
            if index == 0 { self.regular_loads.fetch_add(1, std::sync::atomic::Ordering::Relaxed); }
            self.base.font(index)
        }
    }
    let base = font_world_with(&[
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf",
    ]);
    assert_eq!(base.book().len(), 2);
    let world = CountWorld { base: &base, regular_loads: Default::default() };
    let mut item = text_item_with_font("مرحبا", "DejaVu Sans");
    if let FrameItem::Text { style, .. } = &mut item { style.italic = true; }
    let doc = shape_document(&world, doc_with(vec![item.clone(), item]));
    assert!(doc.pages[0].items.iter().all(|item|matches!(item,FrameItem::TextShaped{font:Some(_),..})));
    assert!(world.regular_loads.load(std::sync::atomic::Ordering::Relaxed) <= 2, "face/shape frio bastam: foram {} consultas", world.regular_loads.load(std::sync::atomic::Ordering::Relaxed));
}

